/* Ejecutar COMPLETO en SSMS conectado al 181.
   Destino: DTM_PEDIDOS_SUGERIDOS.ods.DIM_CLIENTE, version V2.
   Origen: [172.16.8.221], maestros de BD_360 y cruces de la consulta adjunta.
   Conserva UNION ALL de histórico y actual, las listas y reglas de FFVV,
   zona y supervisor. No elige arbitrariamente entre clientes duplicados.
   Las listas se evalúan localmente porque OPENQUERY admite solo 8 KB.
   https://learn.microsoft.com/sql/t-sql/functions/openquery-transact-sql
   quintil usa la regla del BI: DIAMANTE=Q1, ORO=Q2, PLATA=Q3,
   BRONCE=Q4, PLOMO=Q5; otras categorías quedan con cadena vacía.
   nombres_vendedores queda NULL: no viene en la consulta.
   No carga DIM_VENDEDORES ni genera el resumen. No modifica V1.
*/
USE [DTM_PEDIDOS_SUGERIDOS];
GO
SET NOCOUNT ON;
SET XACT_ABORT ON;
SET ANSI_WARNINGS ON;

DECLARE @Version varchar(20) = 'V2';
DECLARE @Insertados bigint;

IF DB_NAME() <> N'DTM_PEDIDOS_SUGERIDOS'
    THROW 50001, N'Base destino incorrecta.', 1;

IF EXISTS (SELECT 1 FROM ods.DIM_CLIENTE WHERE version = @Version)
    THROW 50002, N'Ya existen clientes V2. Revisar antes de repetir la carga.', 1;

IF OBJECT_ID('tempdb..#RucRRVVV2') IS NOT NULL DROP TABLE #RucRRVVV2;
IF OBJECT_ID('tempdb..#RucMiniV2') IS NOT NULL DROP TABLE #RucMiniV2;
IF OBJECT_ID('tempdb..#ClientesBaseV2') IS NOT NULL DROP TABLE #ClientesBaseV2;
IF OBJECT_ID('tempdb..#SupervisoresV2') IS NOT NULL DROP TABLE #SupervisoresV2;
IF OBJECT_ID('tempdb..#CargaClientesV2') IS NOT NULL DROP TABLE #CargaClientesV2;

CREATE TABLE #RucRRVVV2 (ruc nvarchar(50) COLLATE DATABASE_DEFAULT NOT NULL PRIMARY KEY);
CREATE TABLE #RucMiniV2 (ruc nvarchar(50) COLLATE DATABASE_DEFAULT NOT NULL PRIMARY KEY);

-- Listas exactas extraídas del archivo proporcionado: 4946 RRVV y 8 mini-cadenas.




IF (SELECT COUNT_BIG(*) FROM #RucRRVVV2) <> 4946
    OR (SELECT COUNT_BIG(*) FROM #RucMiniV2) <> 8
    THROW 50003, N'Las listas de RUC están incompletas. Ejecutar el archivo completo.', 1;

/* Lecturas remotas fuera de la transacción local.
   Se explicitan las siete columnas del UNION ALL original.
   No se recorta ni normaliza el RUC. CONVERT(max) evita truncarlo al leer.
*/
SELECT remoto.*
INTO #ClientesBaseV2
FROM OPENQUERY([172.16.8.221], '
    WITH cte AS (
        SELECT ruc, farmacia, [Dpto / Distrito], [Dirección],
               [Descripción Región], Departamento, [Código Brick]
        FROM [BD_360].[dbo].[mae_ruc_fr_his]
        UNION ALL
        SELECT ruc, farmacia, [Dpto / Distrito], [Dirección],
               [Descripción Región], Departamento, [Código Brick]
        FROM [BD_360].[dbo].[mae_ruc_fr]
    )
    SELECT
        CONVERT(nvarchar(max), R.ruc) AS ruc,
        CONVERT(nvarchar(max), R.farmacia) AS farmacia,
        CONVERT(nvarchar(max), R.[Dirección]) AS direccion,
        CONVERT(nvarchar(max), COALESCE(C.GRUPOCLIENTE2, ''SIN CLASIFICACION'')) AS grupo_cliente,
        CONVERT(nvarchar(max), C.ZONABASE) AS zona_comercial,
        CONVERT(nvarchar(max), CASE
            WHEN C.ZONABASE IS NULL OR C.ZONABASE = '''' THEN ''SIN CLASIFICACION''
            ELSE C.ZONABASE
        END) AS zonabase,
        CONVERT(nvarchar(max), B.Lima_Provincias) AS lima_provincias,
        CONVERT(nvarchar(max), B.Departamento) AS departamento,
        CONVERT(nvarchar(max), B.Dpto_Distrito) AS distrito,
        CONVERT(nvarchar(max), B.[Descripción_Región]) AS region,
        CONVERT(nvarchar(max), B.[Descripción_Brick]) AS brick,
        CONVERT(varchar(max), B.[Código_Brick]) AS codigo_brick,
        CONVERT(nvarchar(max), CAT.CTG_PAIS) AS categorizacion
    FROM cte AS R
    LEFT JOIN [BD_BussinessI].[dbo].[MAESTROCLIENTES] AS C
        ON R.ruc = C.DOCIDENTIDAD
    LEFT JOIN [BD_McdoFarmaceutico].[ddd].[MAE_BRICK] AS B
        ON R.[Código Brick] = B.[Código_Brick]
    LEFT JOIN [BD_360].[dbo].[cat_pais_fr] AS CAT
        ON CAT.CDG_DOCIDENTIDAD = R.ruc
') AS remoto;

SELECT remoto.zonabase, remoto.nombreSSVV
INTO #SupervisoresV2
FROM OPENQUERY([172.16.8.221], '
    SELECT DISTINCT
        CONVERT(nvarchar(max), zonaBase) AS zonabase,
        CONVERT(nvarchar(max), nombreSSVV) AS nombreSSVV
    FROM [BD_BussinessI].[ods].[TAB_FFVV]
    WHERE grupoFFVV = ''RRVV''
') AS remoto;

/* Las listas originales de zona y FFVV son idénticas.
   RRVV tiene precedencia sobre MINI-CADENAS, como en ambos CASE originales.
   Se conserva el cruce de supervisores por zonaCliente (no por zonabase).
*/
;WITH BaseClasificada AS (
    SELECT b.*,
        CASE WHEN rr.ruc IS NOT NULL OR mini.ruc IS NOT NULL
            THEN b.zona_comercial ELSE b.distrito END AS zona_cliente,
        CASE WHEN rr.ruc IS NOT NULL THEN N'RRVV'
             WHEN mini.ruc IS NOT NULL THEN N'MINI-CADENAS'
             ELSE N'RRMM' END AS ffvv
    FROM #ClientesBaseV2 AS b
    LEFT JOIN #RucRRVVV2 AS rr ON rr.ruc = b.ruc COLLATE DATABASE_DEFAULT
    LEFT JOIN #RucMiniV2 AS mini ON mini.ruc = b.ruc COLLATE DATABASE_DEFAULT
)
SELECT
    b.ruc,
    b.farmacia,
    CONCAT(b.ruc, N' - ', b.farmacia) AS cp_cliente,
    b.direccion,
    b.grupo_cliente,
    b.categorizacion,
    b.lima_provincias,
    b.departamento,
    b.distrito,
    b.region,
    b.brick,
    b.codigo_brick,
    b.zona_cliente,
    b.zonabase,
    b.ffvv,
    CASE WHEN b.ffvv = N'RRVV' THEN m.nombreSSVV
         WHEN b.ffvv = N'MINI-CADENAS' THEN N'CADENAS'
         ELSE N'SUPERVISORES MKT' END AS supervisor
INTO #CargaClientesV2
FROM BaseClasificada AS b
LEFT JOIN #SupervisoresV2 AS m
    ON m.zonabase COLLATE DATABASE_DEFAULT = b.zona_cliente COLLATE DATABASE_DEFAULT;

IF NOT EXISTS (SELECT 1 FROM #CargaClientesV2)
    THROW 50004, N'La consulta de origen no devolvió clientes. No se insertó nada.', 1;

IF EXISTS (
    SELECT 1 FROM #CargaClientesV2
    WHERE NULLIF(LTRIM(RTRIM(ruc)), N'') IS NULL
)
    THROW 50005, N'Hay clientes sin RUC. Revisar la fuente antes de cargar.', 1;

/* UNION ALL y los cruces pueden producir más de una fila por RUC.
   No usar ROW_NUMBER sin una regla de negocio para descartar esas filas.
*/
IF EXISTS (
    SELECT ruc COLLATE DATABASE_DEFAULT
    FROM #CargaClientesV2
    GROUP BY ruc COLLATE DATABASE_DEFAULT
    HAVING COUNT_BIG(*) > 1
)
BEGIN
    SELECT ruc COLLATE DATABASE_DEFAULT AS ruc, COUNT_BIG(*) AS filas
    FROM #CargaClientesV2
    GROUP BY ruc COLLATE DATABASE_DEFAULT
    HAVING COUNT_BIG(*) > 1;

    SELECT c.*
    FROM #CargaClientesV2 AS c
    WHERE EXISTS (
        SELECT 1 FROM #CargaClientesV2 AS d
        WHERE d.ruc COLLATE DATABASE_DEFAULT = c.ruc COLLATE DATABASE_DEFAULT
        GROUP BY d.ruc COLLATE DATABASE_DEFAULT
        HAVING COUNT_BIG(*) > 1
    )
    ORDER BY c.ruc;

    THROW 50006, N'Hay RUC duplicados. Revisar histórico/actual y cruces de clientes, categoría, brick o supervisor. No se insertó nada.', 1;
END;

BEGIN TRY
    BEGIN TRANSACTION;

    IF EXISTS (
        SELECT 1 FROM ods.DIM_CLIENTE WITH (UPDLOCK, HOLDLOCK)
        WHERE version = @Version
    )
        THROW 50007, N'Otra sesión ya cargó clientes V2. Se cancela esta inserción.', 1;

        version, ruc, farmacia, cp_cliente, direccion, grupo_cliente,
        categorizacion, quintil, lima_provincias, departamento, distrito,
        region, brick, codigo_brick, zona_cliente, zonabase, ffvv,
        nombres_vendedores, supervisor
    )
    SELECT
        @Version, ruc, farmacia, cp_cliente, direccion, grupo_cliente,
        categorizacion,
        CASE UPPER(categorizacion)
            WHEN N'DIAMANTE' THEN 'Q1'
            WHEN N'ORO' THEN 'Q2'
            WHEN N'PLATA' THEN 'Q3'
            WHEN N'BRONCE' THEN 'Q4'
            WHEN N'PLOMO' THEN 'Q5'
            ELSE ''
        END AS quintil,
        lima_provincias, departamento, distrito,
        region, brick, codigo_brick, zona_cliente, zonabase, ffvv,
        NULL, supervisor
    FROM #CargaClientesV2;

    SET @Insertados = @@ROWCOUNT;
    COMMIT TRANSACTION;
END TRY
BEGIN CATCH
    IF XACT_STATE() <> 0 ROLLBACK TRANSACTION;
    THROW;
END CATCH;

SELECT @Version AS version, @Insertados AS clientes_insertados;

SELECT version, ffvv, COUNT_BIG(*) AS clientes
FROM ods.DIM_CLIENTE
WHERE version = @Version
GROUP BY version, ffvv
ORDER BY ffvv;

SELECT version, categorizacion, quintil, COUNT_BIG(*) AS clientes
FROM ods.DIM_CLIENTE
WHERE version = @Version
GROUP BY version, categorizacion, quintil
ORDER BY categorizacion;

/* Resumen de campos pendientes para revisión; no se inventan asignaciones. */
SELECT
    COUNT_BIG(*) AS clientes,
    SUM(CONVERT(bigint, CASE WHEN NULLIF(LTRIM(RTRIM(categorizacion)), N'') IS NULL THEN 1 ELSE 0 END)) AS sin_categoria,
    SUM(CONVERT(bigint, CASE WHEN NULLIF(LTRIM(RTRIM(supervisor)), N'') IS NULL THEN 1 ELSE 0 END)) AS sin_supervisor,
    SUM(CONVERT(bigint, CASE WHEN zonabase = N'SIN CLASIFICACION' THEN 1 ELSE 0 END)) AS sin_zonabase,
    SUM(CONVERT(bigint, CASE WHEN NULLIF(quintil, '') IS NULL THEN 1 ELSE 0 END)) AS sin_quintil
FROM ods.DIM_CLIENTE
WHERE version = @Version;

DROP TABLE #CargaClientesV2;
DROP TABLE #SupervisoresV2;
DROP TABLE #ClientesBaseV2;
DROP TABLE #RucMiniV2;
DROP TABLE #RucRRVVV2;
